insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b1co27tsr073', '[{"giong":"coral","chu":"Les trains de nuit reviennent en Europe. Depuis décembre, une nouvelle ligne relie Paris à Berlin en douze heures, trois fois par semaine. À bord, des couchettes à partir de soixante-dix euros et des cabines privées pour deux personnes. Pourquoi ce retour ? D''abord, pour l''environnement : un trajet en train de nuit émet beaucoup moins de gaz à effet de serre que l''avion. Ensuite, parce que les voyageurs économisent une nuit d''hôtel. Nous avons interrogé un passager."},{"giong":"onyx","chu":"Je pars à Berlin pour le travail. Avant, je prenais l''avion, mais entre l''aéroport, les contrôles et les retards, je perdais presque autant de temps. Là, je monte dans le train à vingt heures, je dors, et j''arrive en plein centre-ville à huit heures. Le seul défaut, c''est le prix des repas à bord : quinze euros pour un sandwich, c''est trop !"}]'::jsonb, '{"loai":"Phóng sự radio","chu_de":"Tàu đêm quay lại châu Âu, tuyến Paris Berlin.","y_chinh":["Tuyến mới 12 giờ, ba chuyến mỗi tuần; giường nằm từ 70 euro.","Lý do: ít khí thải hơn máy bay và đỡ một đêm khách sạn.","Một hành khách đi công tác thấy tiện hơn máy bay; chỉ chê đồ ăn trên tàu đắt (15 euro một bánh mì)."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b1co26p2h072', '[{"giong":"nova","chu":"Sur le toit d''un supermarché de Lyon, un jardin de deux mille mètres carrés produit des légumes depuis le printemps. Ils sont vendus directement au rez-de-chaussée, dans le magasin. Nous avons rencontré Bastien, le responsable du jardin."},{"giong":"echo","chu":"Nous cultivons une trentaine de variétés : tomates, salades, herbes aromatiques. Nous n''utilisons aucun pesticide. L''arrosage se fait avec l''eau de pluie récupérée sur le toit. Nous sommes quatre salariés, et des écoles viennent visiter chaque semaine."}]'::jsonb, '{"loai":"Phóng sự radio","chu_de":"Vườn rau trên mái một siêu thị ở Lyon.","y_chinh":["Vườn 2 000 m², rau bán ngay ở tầng trệt.","Khoảng 30 loại rau, không thuốc trừ sâu, tưới bằng nước mưa.","Bốn nhân viên; trường học đến tham quan mỗi tuần."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b1co25llo071', '[{"giong":"shimmer","chu":"Le salon de l''emploi des jeunes aura lieu le jeudi vingt-trois mars, au parc des expositions, de neuf heures à dix-sept heures. Plus de cent vingt entreprises seront présentes, surtout dans l''hôtellerie, le commerce et l''informatique. Des ateliers gratuits permettront de préparer son CV et de s''entraîner aux entretiens. Venez avec plusieurs exemplaires de votre CV. L''entrée est gratuite, mais l''inscription en ligne est obligatoire. Une navette partira de la gare toutes les quinze minutes."}]'::jsonb, '{"loai":"Thông báo","chu_de":"Hội chợ việc làm cho người trẻ.","y_chinh":["Thứ năm 23 tháng 3, khu triển lãm, từ 9 h đến 17 h, hơn 120 doanh nghiệp.","Có xưởng miễn phí chuẩn bị CV và luyện phỏng vấn; mang nhiều bản CV.","Vào cửa miễn phí nhưng phải đăng ký trên mạng; xe đưa đón từ ga 15 phút một chuyến."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b1co24g6q070', '[{"giong":"echo","chu":"À partir du premier février, la ville de Saint-Rémy change les règles du tri. Tous les emballages en plastique, même les pots de yaourt, iront dans la poubelle jaune. Le verre continue d''aller dans les conteneurs de rue. Les déchets de cuisine seront ramassés le mardi, dans un petit bac marron distribué gratuitement en mairie. L''objectif : réduire de moitié les déchets brûlés d''ici trois ans."}]'::jsonb, '{"loai":"Thông báo của thành phố","chu_de":"Quy định phân loại rác mới ở Saint-Rémy.","y_chinh":["Từ 1 tháng 2, mọi bao bì nhựa, kể cả hũ sữa chua, bỏ thùng vàng.","Thuỷ tinh vẫn bỏ vào thùng ngoài phố; rác bếp thu thứ ba, thùng nâu nhỏ phát miễn phí ở toà thị chính.","Mục tiêu: giảm một nửa rác đem đốt trong ba năm."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b1co23bti06z', '[{"giong":"coral","chu":"Bonjour, ici le centre de formation Langues Plus. Votre cours de conversation commence le lundi quatorze octobre, à dix-huit heures trente, salle douze, au deuxième étage. Le cours dure dix semaines et coûte deux cent vingt euros. N''oubliez pas d''apporter une photo d''identité. Pour toute question, appelez Madame Lefèvre au zéro quatre, soixante-dix-huit, cinquante-deux, dix-neuf, trente."}]'::jsonb, '{"loai":"Tin nhắn thoại","chu_de":"Trung tâm Langues Plus báo lịch khoá học hội thoại.","y_chinh":["Bắt đầu thứ hai 14 tháng 10 lúc 18 h 30, phòng 12, tầng hai.","Khoá học mười tuần, 220 euro; mang ảnh thẻ.","Có câu hỏi thì gọi bà Lefèvre."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b1co227n806y', '[{"giong":"alloy","chu":"Dans notre magazine de société, un phénomène qui se développe : la colocation entre générations. Le principe : une personne âgée qui vit seule loue une chambre à un étudiant, pour un prix très bas. En échange, l''étudiant rend quelques services. Inès et Robert vivent ensemble depuis un an."},{"giong":"nova","chu":"Je paie cent cinquante euros par mois, alors qu''un studio à Paris coûte au moins huit cents euros. En échange, je dîne avec Robert trois soirs par semaine et je fais quelques courses. Ce n''est pas une obligation pour moi, c''est devenu un vrai plaisir."},{"giong":"onyx","chu":"Depuis la mort de ma femme, la maison était trop silencieuse. Inès m''a appris à envoyer des photos à mes petits-enfants avec mon téléphone. Et moi, je lui apprends à cuisiner ! Ma fille était inquiète au début, mais maintenant elle est rassurée de savoir que je ne suis pas seul la nuit."},{"giong":"alloy","chu":"L''association qui les a mis en relation a déjà formé plus de deux cents binômes dans la région."}]'::jsonb, '{"loai":"Phóng sự radio","chu_de":"Ở ghép giữa hai thế hệ.","y_chinh":["Người già sống một mình cho sinh viên thuê phòng rất rẻ, đổi lại sinh viên giúp vài việc.","Inès trả 150 euro thay vì ít nhất 800 euro cho một studio ở Paris, ăn tối với ông Robert ba buổi mỗi tuần.","Ông Robert bớt cô đơn sau khi vợ mất, con gái yên tâm; hiệp hội đã ghép hơn 200 cặp trong vùng."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b1co213t406x', '[{"giong":"coral","chu":"Depuis la rentrée, les écoles primaires de la région testent trente minutes d''activité physique chaque jour, en plus des cours d''éducation physique. Les élèves font des exercices dans la cour ou même dans la classe, entre deux leçons. Premier bilan avec Thomas Girard, professeur des écoles à Annecy."},{"giong":"onyx","chu":"Honnêtement, j''étais sceptique au début. Je me disais : on n''a déjà pas assez de temps pour les maths et le français ! Mais après deux mois, je vois la différence. Les enfants sont plus calmes l''après-midi et ils se concentrent mieux. Le seul problème, c''est la météo : quand il pleut, faire bouger vingt-huit élèves dans une petite classe, c''est un vrai défi !"}]'::jsonb, '{"loai":"Phóng sự radio","chu_de":"Thử nghiệm 30 phút vận động mỗi ngày ở trường tiểu học.","y_chinh":["Học sinh tập trong sân hoặc ngay trong lớp giữa hai bài, ngoài giờ thể dục.","Thầy Girard lúc đầu nghi ngờ vì sợ mất giờ toán và tiếng Pháp.","Sau hai tháng, trẻ bình tĩnh và tập trung hơn buổi chiều; khó nhất là ngày mưa trong lớp chật."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b1co20zfr06w', '[{"giong":"echo","chu":"On pensait que les liseuses et les écrans allaient faire disparaître le livre papier. Pourtant, chez les jeunes, il revient à la mode. Nous sommes allés dans une librairie de Bordeaux."},{"giong":"shimmer","chu":"Depuis trois ans, je vois de plus en plus de clients de quinze à vingt-cinq ans. Ils découvrent des romans sur les réseaux sociaux, puis ils viennent les acheter ici. Pour eux, le livre papier, c''est un objet qu''on garde, qu''on prête, qu''on prend en photo. Beaucoup me disent aussi qu''ils passent assez de temps sur les écrans dans la journée. Le soir, lire un vrai livre les aide à se déconnecter. Nous avons même créé un club de lecture le mercredi soir : il y a déjà trente inscrits."}]'::jsonb, '{"loai":"Phóng sự radio","chu_de":"Sách giấy quay lại được giới trẻ yêu thích.","y_chinh":["Hiệu sách ở Bordeaux có ngày càng nhiều khách 15 đến 25 tuổi, tìm sách qua mạng xã hội rồi đến mua.","Với họ, sách giấy là vật để giữ, cho mượn, chụp ảnh, và giúp rời màn hình buổi tối.","Hiệu sách mở câu lạc bộ đọc tối thứ tư, đã có 30 người đăng ký."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b1co19urt06v', '[{"giong":"echo","chu":"Notre invitée aujourd''hui exerce un métier encore très masculin : Lucie Garnier est sapeuse-pompière à Grenoble depuis six ans. Lucie, pourquoi ce métier ?"},{"giong":"nova","chu":"Depuis toute petite, je voulais aider les gens. Mon père était pompier volontaire, et je l''accompagnais aux portes ouvertes de la caserne. Après le bac, j''ai fait des études de sport, puis j''ai passé le concours."},{"giong":"echo","chu":"Comment se passe une journée type ?"},{"giong":"nova","chu":"Nous travaillons par gardes de vingt-quatre heures. Le matin, il y a le sport et la vérification du matériel. Ensuite, on attend les appels. Contrairement à ce qu''on croit, les incendies ne représentent qu''environ dix pour cent de nos interventions. La plupart du temps, nous aidons des personnes malades ou blessées."},{"giong":"echo","chu":"Et être une femme, est-ce difficile ?"},{"giong":"nova","chu":"Au début, certains collègues doutaient de moi. Mais j''ai les mêmes résultats aux tests physiques qu''eux, et aujourd''hui, l''équipe me fait totalement confiance. Dans ma caserne, nous sommes quatre femmes sur soixante."}]'::jsonb, '{"loai":"Phỏng vấn radio","chu_de":"Lucie Garnier, nữ lính cứu hoả ở Grenoble.","y_chinh":["Từ nhỏ cô muốn giúp người, bố là lính cứu hoả tình nguyện; học thể thao rồi thi tuyển.","Làm ca 24 giờ; cháy nhà chỉ chiếm khoảng 10 % số lần can thiệp, phần lớn là cứu người ốm, bị thương.","Lúc đầu có đồng nghiệp nghi ngờ, nay cả đội tin cô; đơn vị có 4 nữ trên 60 người."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b1co18r2306u', '[{"giong":"coral","chu":"Quels métiers recruteront le plus dans dix ans ? Selon une étude du cabinet Avenir Emploi, les besoins seront très forts dans trois domaines. D''abord la santé : il manquera des aides-soignants et des infirmiers, car la population vieillit. Ensuite, la transition écologique : installateurs de panneaux solaires, réparateurs de vélos électriques, conseillers en rénovation des logements. Enfin, le numérique, avec les spécialistes de la cybersécurité. L''étude note aussi qu''un métier sur trois de demain n''existe pas encore aujourd''hui. Les auteurs conseillent donc aux jeunes de développer des compétences générales : savoir apprendre, travailler en équipe et communiquer."}]'::jsonb, '{"loai":"Bản tin radio","chu_de":"Những ngành nghề sẽ tuyển nhiều trong mười năm tới.","y_chinh":["Y tế: thiếu hộ lý và y tá vì dân số già đi.","Chuyển đổi xanh: lắp pin mặt trời, sửa xe đạp điện, tư vấn cải tạo nhà; và an ninh mạng.","Một trên ba nghề tương lai chưa có hôm nay, nên người trẻ cần biết tự học, làm việc nhóm và giao tiếp."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b1co17ksk06t', '[{"giong":"alloy","chu":"Maëlle, vingt et un ans, étudiante en communication, vient de terminer son premier stage. Elle nous raconte."},{"giong":"shimmer","chu":"J''ai fait mon stage dans une petite agence de publicité à Marseille, pendant trois mois. Les deux premières semaines, c''était dur : je faisais surtout des photocopies et je préparais le café ! Puis ma tutrice m''a confié un vrai projet : la campagne d''un festival de cinéma. J''ai écrit les textes pour les réseaux sociaux. J''étais payée un peu plus de six cents euros par mois, ce qui ne suffit pas pour vivre à Marseille, donc mes parents m''ont aidée. Mais j''ai beaucoup appris, et l''agence m''a proposé un contrat pour l''été."}]'::jsonb, '{"loai":"Lời kể trên radio","chu_de":"Maëlle kể về kỳ thực tập đầu tiên.","y_chinh":["Ba tháng ở một công ty quảng cáo nhỏ tại Marseille.","Hai tuần đầu chủ yếu photo và pha cà phê, sau đó được giao viết nội dung mạng xã hội cho một liên hoan phim.","Lương hơn 600 euro không đủ sống nên bố mẹ phụ; công ty mời cô làm hợp đồng mùa hè."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b1co16f2i06s', '[{"giong":"alloy","chu":"Julien Mercier a été banquier pendant quinze ans. À quarante et un ans, il a tout quitté pour devenir boulanger. Julien, qu''est-ce qui vous a décidé ?"},{"giong":"onyx","chu":"Je gagnais bien ma vie, mais je m''ennuyais. Je passais mes journées devant des tableaux de chiffres. Un week-end, j''ai fait un stage de pain chez un artisan, et j''ai su tout de suite que c''était ça que je voulais faire."},{"giong":"alloy","chu":"Ça n''a pas été trop difficile ?"},{"giong":"onyx","chu":"Si, bien sûr. J''ai suivi une formation de neuf mois, et ma femme a dû payer presque toutes les dépenses de la famille pendant ce temps. Aujourd''hui, je me lève à quatre heures du matin et je gagne deux fois moins qu''avant. Mais je suis heureux : je fais quelque chose de concret, et je vois les clients sourire."}]'::jsonb, '{"loai":"Phỏng vấn radio","chu_de":"Julien bỏ nghề ngân hàng năm 41 tuổi để làm thợ làm bánh.","y_chinh":["Anh kiếm tiền tốt nhưng chán cảnh ngồi trước bảng số liệu; một khoá học làm bánh cuối tuần đã quyết định tất cả.","Anh học chín tháng, vợ gánh gần hết chi tiêu gia đình.","Nay anh dậy 4 giờ sáng, thu nhập còn một nửa nhưng hạnh phúc vì làm việc cụ thể và thấy khách cười."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b1co15bq006r', '[{"giong":"echo","chu":"Depuis deux ans, Sarah Klein, graphiste, travaille presque entièrement de chez elle. Sarah, quels sont les avantages ?"},{"giong":"nova","chu":"D''abord, je ne perds plus une heure et demie par jour dans les transports. J''ai plus de temps pour ma famille, et je suis plus concentrée : au bureau, on était douze dans la même pièce, avec beaucoup de bruit."},{"giong":"echo","chu":"Et les inconvénients ?"},{"giong":"nova","chu":"La solitude, surtout. Certains jours, je ne parle à personne. Et il est difficile de s''arrêter : l''ordinateur est toujours là, sur la table du salon. Maintenant, je vais au bureau le jeudi, pour voir mes collègues, et le soir, à dix-neuf heures, j''éteins tout."}]'::jsonb, '{"loai":"Phỏng vấn radio","chu_de":"Sarah, nhà thiết kế đồ hoạ, làm việc tại nhà.","y_chinh":["Ưu điểm: đỡ một tiếng rưỡi đi lại, có thời gian cho gia đình, tập trung hơn văn phòng ồn.","Nhược điểm: cô đơn và khó dừng làm việc.","Giải pháp: thứ năm lên văn phòng gặp đồng nghiệp, 19 h tắt hết máy."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b1co1364u06p', '[{"giong":"alloy","chu":"Bienvenue dans La parole aux auditeurs. Notre question du jour : faut-il interdire les voitures dans le centre-ville ? Premier appel, Gérard, de Tours."},{"giong":"onyx","chu":"Bonjour. Moi, je suis commerçant, et franchement, c''est une catastrophe. Mes clients ne peuvent plus se garer, ils vont au centre commercial. J''ai perdu vingt pour cent de mon chiffre d''affaires."},{"giong":"alloy","chu":"Merci Gérard. Nadia, de Rennes, vous êtes en ligne."},{"giong":"nova","chu":"Bonjour ! Moi, je trouve ça génial. Je me promène avec mes enfants sans avoir peur, l''air est plus propre. Je ne reviendrais en arrière pour rien au monde."},{"giong":"alloy","chu":"Et enfin, Michel, de Lyon."},{"giong":"echo","chu":"Je suis partagé. L''idée est bonne, mais pour les personnes âgées comme ma mère, c''est compliqué. Il faudrait plus de bus et de navettes gratuites."}]'::jsonb, '{"loai":"Chương trình radio có thính giả gọi đến","chu_de":"Có nên cấm ô tô ở trung tâm thành phố.","y_chinh":["Gérard, chủ cửa hàng: thảm hoạ, khách không đỗ xe được, doanh thu mất 20 %.","Nadia: rất thích, đi dạo với con không sợ, không khí sạch hơn.","Michel: phân vân, ý hay nhưng khó cho người già; cần thêm xe buýt và xe đưa đón miễn phí."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b1co110k706n', '[{"giong":"alloy","chu":"Service client Fibrolink, Mathieu à votre écoute."},{"giong":"coral","chu":"Bonjour. Écoutez, ça fait maintenant dix jours que je n''ai plus internet. J''ai déjà appelé trois fois, et à chaque fois on me promet un technicien qui ne vient jamais. Ce n''est pas normal !"},{"giong":"alloy","chu":"Je comprends, madame. Je vois votre dossier… Un technicien peut passer mardi prochain."},{"giong":"coral","chu":"Mardi prochain ? Mais je travaille de chez moi, moi ! Je perds des clients. Je suis vraiment déçue, je suis chez vous depuis huit ans."},{"giong":"alloy","chu":"Je vous propose un mois d''abonnement gratuit pour vous excuser."},{"giong":"coral","chu":"Bon… c''est un geste, merci. Mais si mardi personne ne vient, je résilie mon contrat."}]'::jsonb, '{"loai":"Cuộc gọi tới tổng đài chăm sóc khách hàng","chu_de":"Khách hàng bực vì mất mạng internet mười ngày.","y_chinh":["Đã gọi ba lần, kỹ thuật viên hứa đến nhưng không đến.","Chị làm việc tại nhà nên mất khách; là khách hàng tám năm và rất thất vọng.","Nhân viên tặng một tháng miễn phí; chị nói sẽ huỷ hợp đồng nếu thứ ba không ai đến."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b1co10xj906m', '[{"giong":"nova","chu":"J''ai une idée pour les vacances : on pourrait faire le tour de l''Islande en camping-car !"},{"giong":"echo","chu":"En camping-car ? Hum… je ne sais pas trop. Ça doit coûter une fortune."},{"giong":"nova","chu":"Pas tant que ça, si on partage avec Lucas et Emma."},{"giong":"echo","chu":"Ah oui, là, je suis tout à fait d''accord. À quatre, c''est beaucoup plus raisonnable. Mais en août, il ne fera pas trop froid là-bas ?"},{"giong":"nova","chu":"Il fera environ quinze degrés. Ce n''est pas la plage, mais c''est parfait pour marcher."},{"giong":"echo","chu":"Bon, tu m''as convaincu. Par contre, conduire huit heures par jour, ça, franchement, j''en doute."}]'::jsonb, '{"loai":"Hội thoại giữa hai người bạn","chu_de":"Bàn chuyện đi vòng quanh Iceland bằng xe nhà di động.","y_chinh":["Người nghe lúc đầu do dự vì sợ tốn kém.","Đồng ý hoàn toàn khi biết chia tiền cho bốn người với Lucas và Emma.","Thấy 15 độ vào tháng 8 là ổn để đi bộ, nhưng vẫn nghi ngờ chuyện lái xe tám giờ mỗi ngày."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b1co09uxi06l', '[{"giong":"alloy","chu":"Comment allez-vous au travail ? Nous avons posé la question dans la rue."},{"giong":"nova","chu":"Je m''appelle Julie. Je prends le vélo tous les jours, même quand il pleut. Ça me prend vingt minutes et je n''ai pas besoin d''aller à la salle de sport !"},{"giong":"onyx","chu":"Moi, c''est Karim. J''habite à trente kilomètres. Je fais du covoiturage avec deux collègues : on partage l''essence et on discute pendant le trajet."},{"giong":"shimmer","chu":"Madame Petit. Je travaille à la maison trois jours par semaine. Les deux autres jours, je prends le train de sept heures douze."},{"giong":"echo","chu":"Hugo. J''ai acheté une voiture électrique l''année dernière. C''est cher au départ, mais je paie beaucoup moins pour l''énergie."}]'::jsonb, '{"loai":"Phỏng vấn ngoài phố (bốn người)","chu_de":"Mỗi người đi làm bằng phương tiện gì.","y_chinh":["Julie đạp xe mỗi ngày, 20 phút, coi như tập thể thao.","Karim ở xa 30 km, đi chung xe với hai đồng nghiệp.","Bà Petit làm ở nhà ba ngày, hai ngày còn lại đi tàu 7 h 12.","Hugo mua ô tô điện: đắt lúc đầu nhưng tốn ít tiền năng lượng."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b1co08ruh06k', '[{"giong":"shimmer","chu":"Agence Habitat, bonjour."},{"giong":"echo","chu":"Bonjour, j''appelle pour l''annonce du deux-pièces rue Pasteur. Il est toujours libre ?"},{"giong":"shimmer","chu":"Oui. Il fait quarante-deux mètres carrés, au troisième étage, sans ascenseur. Le loyer est de six cent quatre-vingts euros, charges comprises."},{"giong":"echo","chu":"Ah, c''est un peu plus que prévu. Nous sommes deux étudiants, avec mon amie Léa. Il faut un garant ?"},{"giong":"shimmer","chu":"Oui, et le dépôt de garantie est d''un mois de loyer. Vous pouvez visiter jeudi à dix-sept heures ?"},{"giong":"echo","chu":"Jeudi, moi, je travaille. Mais Léa est libre, elle peut venir à ma place."},{"giong":"shimmer","chu":"Très bien. Qu''elle apporte une pièce d''identité."}]'::jsonb, '{"loai":"Cuộc gọi tới công ty nhà đất","chu_de":"Hỏi thuê căn hộ hai phòng ở phố Pasteur.","y_chinh":["Căn hộ 42 m², tầng ba không thang máy, 680 euro đã gồm phí.","Hai sinh viên thuê cần người bảo lãnh và tiền cọc một tháng.","Người gọi bận thứ năm nên Léa đi xem nhà thay, nhớ mang giấy tờ tuỳ thân."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b1co07ozd06j', '[{"giong":"echo","chu":"La ville de Montval aura bientôt son tramway. Les travaux commenceront en mars prochain et la première ligne devrait ouvrir en septembre deux mille vingt-neuf. Les explications de Nadia Benali, adjointe au maire chargée des transports."},{"giong":"coral","chu":"La ligne fera douze kilomètres, de la gare jusqu''à l''hôpital, en passant par l''université et le centre commercial. Il y aura vingt stations. Un tramway passera toutes les six minutes aux heures de pointe. Le projet coûte trois cent quarante millions d''euros, payés en partie par la région. Pendant les travaux, la rue de la République sera fermée aux voitures, mais les commerces resteront ouverts."}]'::jsonb, '{"loai":"Bản tin radio có phỏng vấn","chu_de":"Thành phố Montval sắp có tàu điện mặt đất.","y_chinh":["Khởi công tháng 3 tới, tuyến đầu dự kiến chạy tháng 9 năm 2029.","Tuyến dài 12 km, 20 trạm, từ nhà ga đến bệnh viện; giờ cao điểm sáu phút một chuyến.","Chi phí 340 triệu euro, vùng chịu một phần; trong lúc thi công phố République cấm ô tô nhưng cửa hàng vẫn mở."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b1co06kvs06i', '[{"giong":"alloy","chu":"Faut-il un uniforme à l''école ? Le débat est ouvert. Marc Lebrun est père de deux enfants, Sophie Aubert est professeure de collège."},{"giong":"onyx","chu":"Moi, je suis pour. Avec un uniforme, il n''y a plus de compétition entre les marques. Les enfants de familles modestes ne se sentent plus différents. Et le matin, on gagne du temps : plus besoin de choisir ses vêtements !"},{"giong":"nova","chu":"Je ne suis pas d''accord. D''abord, un uniforme coûte cher, environ deux cents euros par an, et ce sont les familles qui paient. Ensuite, les vêtements permettent aux adolescents d''exprimer leur personnalité. Et puis, les inégalités ne disparaissent pas : on les voit dans les chaussures, les sacs, les téléphones."},{"giong":"onyx","chu":"Peut-être, mais c''est un premier pas."}]'::jsonb, '{"loai":"Tranh luận trên radio","chu_de":"Có nên mặc đồng phục ở trường không.","y_chinh":["Ông Lebrun ủng hộ: hết ganh đua hàng hiệu, con nhà nghèo không thấy khác biệt, sáng đỡ mất thời gian.","Cô Aubert phản đối: đồng phục tốn khoảng 200 euro mỗi năm, tuổi teen cần thể hiện cá tính.","Cô cho rằng bất bình đẳng vẫn hiện qua giày, cặp, điện thoại; ông Lebrun đáp đó là bước đầu."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b1co05h8y06h', '[{"giong":"nova","chu":"D''après une enquête publiée ce matin par l''institut Opinion Plus, six Français sur dix font du sport au moins une fois par semaine. C''est plus qu''il y a dix ans, quand ils n''étaient que quarante-cinq pour cent. Le sport préféré reste la marche, devant la course à pied et le vélo. Les femmes sont désormais aussi nombreuses que les hommes à pratiquer une activité régulière. En revanche, les jeunes de dix-huit à vingt-quatre ans font moins de sport qu''avant : seulement un sur deux. Le manque de temps est la raison la plus souvent citée, avant le prix des clubs."}]'::jsonb, '{"loai":"Bản tin radio","chu_de":"Khảo sát người Pháp và thể thao.","y_chinh":["Sáu trên mười người Pháp chơi thể thao ít nhất mỗi tuần một lần, tăng so với 45 % mười năm trước.","Đi bộ là môn được chuộng nhất, rồi chạy bộ và xe đạp; nữ giới nay tập nhiều ngang nam giới.","Người trẻ 18 đến 24 tuổi tập ít hơn trước, chỉ một nửa; lý do chính là thiếu thời gian, rồi mới tới giá câu lạc bộ."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b1co038nt06f', '[{"giong":"echo","chu":"Bonjour à tous. Aujourd''hui, nous parlons du temps que les adolescents passent devant les écrans. Avec nous, la psychologue Inès Durand."},{"giong":"nova","chu":"Dans notre enquête auprès de deux cents lycéens, les jeunes passent en moyenne cinq heures par jour sur leur téléphone, en dehors des cours. Le problème, ce n''est pas seulement le temps : c''est surtout le soir. Beaucoup d''adolescents regardent leur écran au lit, et ils dorment moins de sept heures par nuit. Mon conseil aux parents : ne pas interdire, mais discuter. Par exemple, on peut décider ensemble que tous les téléphones restent dans la cuisine après vingt-deux heures."}]'::jsonb, '{"loai":"Chương trình radio có chuyên gia","chu_de":"Thời gian dùng màn hình của thanh thiếu niên.","y_chinh":["Khảo sát 200 học sinh: trung bình 5 giờ mỗi ngày trên điện thoại ngoài giờ học.","Vấn đề lớn nhất là dùng màn hình trên giường buổi tối, ngủ dưới bảy tiếng.","Lời khuyên cho phụ huynh: không cấm mà trao đổi, ví dụ để điện thoại ở bếp sau 22 h."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b1co024bm06e', '[{"giong":"shimmer","chu":"Vous aimez la musique et vous avez du temps libre cet été ? Le festival Les Nuits du Port revient du douze au quinze juillet, et cette année, nous cherchons cent cinquante bénévoles ! Accueil du public, vente des boissons, aide aux artistes : il y en a pour tous les goûts. En échange de quatre soirées de travail, vous recevrez un pass gratuit pour tous les concerts et un tee-shirt du festival. Aucune expérience n''est demandée, mais il faut avoir au moins dix-huit ans. Inscriptions sur notre site avant le trente juin."}]'::jsonb, '{"loai":"Quảng cáo trên radio","chu_de":"Lễ hội Les Nuits du Port tìm 150 tình nguyện viên.","y_chinh":["Lễ hội từ 12 đến 15 tháng 7.","Việc gồm đón khách, bán đồ uống, hỗ trợ nghệ sĩ; đổi bốn buổi tối làm việc lấy vé xem tất cả các buổi diễn và áo phông.","Không cần kinh nghiệm, phải từ 18 tuổi, đăng ký trên mạng trước 30 tháng 6."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('b1co01zf706d', '[{"giong":"nova","chu":"Ce matin, dans notre émission, direction le village de Saint-Aubin, où une nouvelle école a ouvert ses portes lundi. Avant, les enfants devaient prendre le car pendant quarante minutes pour aller en classe dans la ville voisine. Nous avons rencontré la directrice, Claire Morel."},{"giong":"coral","chu":"C''est un grand jour pour le village. Nous avons trois classes et soixante-cinq élèves. Le bâtiment est construit en bois et il produit sa propre électricité grâce à des panneaux solaires. Les parents sont ravis : les enfants dorment plus le matin et ils peuvent rentrer déjeuner à la maison. Notre projet, c''est aussi d''ouvrir la bibliothèque de l''école aux habitants, le samedi matin."}]'::jsonb, '{"loai":"Phóng sự radio","chu_de":"Ngôi trường mới ở làng Saint-Aubin.","y_chinh":["Trước đây trẻ phải đi xe 40 phút sang thành phố bên cạnh.","Trường có ba lớp, 65 học sinh, nhà gỗ tự sản xuất điện bằng pin mặt trời.","Phụ huynh hài lòng vì con ngủ thêm và về nhà ăn trưa; trường dự định mở thư viện cho dân làng sáng thứ bảy."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a2co18wic05w', '[{"giong":"alloy","chu":"Bonjour et bienvenue dans « Le café des auditeurs ». Ce matin, notre question : travailler à la maison, c''est une bonne idée ? Premier appel, Nathalie, de Toulouse."},{"giong":"shimmer","chu":"Bonjour. Moi, je travaille chez moi trois jours par semaine depuis deux ans. Je gagne une heure et demie de transport chaque jour, alors je dors plus et je suis moins stressée. Mais parfois, mes collègues me manquent."},{"giong":"alloy","chu":"Merci Nathalie. Deuxième appel, Bruno, de Lille."},{"giong":"onyx","chu":"Bonjour. Pour moi, c''est non ! J''ai essayé pendant six mois, mais j''ai deux jeunes enfants et l''appartement est petit. Je n''arrivais pas à me concentrer. Maintenant, je vais au bureau tous les jours et je suis beaucoup plus efficace."},{"giong":"alloy","chu":"Deux avis bien différents ! Et vous, qu''en pensez-vous ? Écrivez-nous sur notre site."}]'::jsonb, '{"loai":"Chương trình radio có thính giả gọi đến","chu_de":"Làm việc ở nhà có phải là ý hay không.","y_chinh":["Nathalie làm ở nhà ba ngày một tuần: đỡ một tiếng rưỡi đi lại, ngủ nhiều hơn, bớt căng thẳng, nhưng nhớ đồng nghiệp.","Bruno phản đối: nhà nhỏ, có hai con nhỏ nên không tập trung được.","Bruno giờ lên văn phòng mỗi ngày và làm việc hiệu quả hơn."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a2co17wdq05v', '[{"giong":"echo","chu":"Aujourd''hui, on parle cuisine. Sophie, vous cuisinez souvent ?"},{"giong":"coral","chu":"Tous les jours ! Pour moi, c''est un plaisir, pas une obligation. Je cuisine le soir pour me détendre après le travail, et le dimanche, je prépare des plats pour toute la semaine. C''est moins cher que le restaurant et c''est meilleur pour la santé."},{"giong":"echo","chu":"Et vous, Lucas ?"},{"giong":"verse","chu":"Moi, je n''aime pas du tout cuisiner. Je n''ai pas le temps et je ne suis pas doué ! Le midi, je mange à la cantine de mon entreprise, et le soir, souvent, je commande une pizza. Mais ma copine cuisine très bien, alors le week-end, je mange bien !"}]'::jsonb, '{"loai":"Phỏng vấn trên radio","chu_de":"Thói quen nấu ăn ở nhà.","y_chinh":["Sophie nấu mỗi ngày để thư giãn, chủ nhật nấu sẵn cho cả tuần: rẻ hơn và tốt cho sức khoẻ.","Lucas không thích nấu: trưa ăn căng tin công ty, tối hay gọi pizza.","Cuối tuần Lucas ăn ngon vì bạn gái nấu giỏi."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a2co16w8b05u', '[{"giong":"nova","chu":"Marc, quel est votre plus beau voyage ?"},{"giong":"ash","chu":"Sans hésiter, le Vietnam, il y a deux ans. Je suis parti un mois avec ma femme. On a commencé par Hanoï, puis on est descendus vers le sud en train."},{"giong":"nova","chu":"Qu''est-ce qui vous a le plus plu ?"},{"giong":"ash","chu":"La cuisine, évidemment ! J''ai mangé une soupe pho tous les matins. Et les gens étaient très accueillants. Par contre, la chaleur à Hô Chi Minh-Ville, c''était difficile pour moi."},{"giong":"nova","chu":"Vous y retournerez ?"},{"giong":"ash","chu":"Oui, l''année prochaine, mais cette fois, je veux visiter le centre du pays, la ville de Hué."}]'::jsonb, '{"loai":"Phỏng vấn","chu_de":"Marc kể chuyến đi Việt Nam, chuyến đi đẹp nhất của anh.","y_chinh":["Hai năm trước, anh đi một tháng cùng vợ, từ Hà Nội vào nam bằng tàu.","Anh thích món ăn (sáng nào cũng ăn phở) và người dân hiếu khách; khó chịu với cái nóng ở TP Hồ Chí Minh.","Năm sau anh muốn quay lại thăm miền Trung, thành phố Huế."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a2co15w3q05t', '[{"giong":"alloy","chu":"Ville ou campagne ? Nous avons posé la question à deux auditeurs. Claire, vous habitez à la campagne depuis trois ans."},{"giong":"shimmer","chu":"Oui, et je ne regrette pas ! C''est plus calme, l''air est plus pur, et ma maison est deux fois plus grande que mon ancien appartement. Le problème, c''est la voiture : je l''utilise pour tout."},{"giong":"alloy","chu":"Karim, vous, vous préférez la ville."},{"giong":"onyx","chu":"Absolument. J''aime sortir le soir, aller au cinéma, voir mes amis. Tout est près de chez moi, je n''ai même pas de voiture. C''est vrai que les loyers sont chers, mais pour moi, ça vaut la peine."}]'::jsonb, '{"loai":"Phỏng vấn trên radio","chu_de":"Sống ở nông thôn hay ở thành phố.","y_chinh":["Claire sống ở nông thôn ba năm: yên tĩnh, không khí sạch, nhà rộng gấp đôi; bất tiện là phải đi xe hơi mọi lúc.","Karim thích thành phố: đi chơi buổi tối, mọi thứ ở gần, không cần xe.","Karim thừa nhận tiền thuê nhà đắt nhưng thấy xứng đáng."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a2co14vr605s', '[{"giong":"echo","chu":"Aujourd''hui, nous recevons Inès, apicultrice. Inès, en quoi consiste votre métier ?"},{"giong":"coral","chu":"Je m''occupe des abeilles et je produis du miel. J''ai environ quarante ruches, à la campagne, près d''Orléans."},{"giong":"echo","chu":"Vous avez toujours voulu faire ce métier ?"},{"giong":"coral","chu":"Pas du tout ! Avant, j''étais comptable dans une banque. Mais je passais toute la journée devant un ordinateur, et je m''ennuyais. Il y a six ans, j''ai tout changé."},{"giong":"echo","chu":"Et aujourd''hui, vous êtes contente ?"},{"giong":"coral","chu":"Oui, très. Je gagne moins d''argent qu''avant, mais je suis plus libre. Le seul problème, c''est l''été : je travaille beaucoup, parfois douze heures par jour."}]'::jsonb, '{"loai":"Phỏng vấn","chu_de":"Inès kể về nghề nuôi ong của mình.","y_chinh":["Inès chăm khoảng 40 tổ ong gần Orléans và làm mật.","Trước đây chị làm kế toán ngân hàng, thấy chán nên đổi nghề sáu năm trước.","Giờ chị kiếm ít tiền hơn nhưng tự do hơn; mùa hè có khi làm 12 giờ một ngày."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a2co13vkl05r', '[{"giong":"nova","chu":"Bonjour Thomas. Vous faites de l''escalade depuis longtemps ?"},{"giong":"onyx","chu":"Bonjour. Oui, depuis dix ans. J''ai commencé à quinze ans, avec mon oncle, dans les Alpes."},{"giong":"nova","chu":"Qu''est-ce que vous aimez dans ce sport ?"},{"giong":"onyx","chu":"Surtout le calme. Quand je grimpe, je ne pense à rien d''autre. Et puis j''adore être dans la nature, loin de la ville."},{"giong":"nova","chu":"Ce n''est pas trop dangereux ?"},{"giong":"onyx","chu":"Non, si on fait attention. Le plus difficile, pour moi, ce n''est pas la peur, c''est la fatigue dans les bras !"},{"giong":"nova","chu":"Vous grimpez souvent ?"},{"giong":"onyx","chu":"Deux fois par semaine en salle, et le week-end dehors, quand il fait beau."}]'::jsonb, '{"loai":"Phỏng vấn","chu_de":"Thomas nói về môn leo núi, niềm đam mê của anh.","y_chinh":["Anh leo núi mười năm, bắt đầu năm 15 tuổi cùng chú ở dãy Alpes.","Anh thích sự yên tĩnh và được ở giữa thiên nhiên.","Khó nhất là mỏi tay, không phải nỗi sợ; anh tập hai lần một tuần trong phòng và cuối tuần leo ngoài trời."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a2co12vfo05q', '[{"giong":"coral","chu":"Message un. Salut Léa, c''est Hugo. Je ne pourrai pas venir au cinéma ce soir : j''ai encore beaucoup de travail. Tu veux qu''on y aille plutôt dimanche après-midi ? Rappelle-moi !"},{"giong":"ash","chu":"Message deux. Bonjour, ici le cabinet du docteur Lambert. Votre rendez-vous du vendredi quatre est avancé au jeudi trois, à la même heure, neuf heures quinze. Si cet horaire ne vous convient pas, merci de nous appeler."},{"giong":"nova","chu":"Message trois. Bonjour, c''est l''école de musique. Les inscriptions pour l''année prochaine commenceront le premier juin. Les cours de guitare sont complets, mais il reste des places en piano et en violon."}]'::jsonb, '{"loai":"Ba tin nhắn thoại","chu_de":"Đổi lịch hẹn và thông báo đăng ký.","y_chinh":["Tin 1: Hugo không đi xem phim tối nay được, rủ Léa chiều chủ nhật.","Tin 2: phòng khám dời hẹn từ thứ sáu ngày 4 sang thứ năm ngày 3, vẫn 9 h 15.","Tin 3: trường nhạc nhận đăng ký từ 1 tháng 6; lớp guitar hết chỗ, còn piano và violon."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a2co11v9d05p', '[{"giong":"onyx","chu":"Il est huit heures, voici le flash info. D''abord, la circulation : un accident a bloqué l''autoroute A six ce matin près de Lyon. Il n''y a pas de blessés, mais les bouchons atteignent dix kilomètres. Ensuite, l''éducation : à partir de la rentrée de septembre, les cantines des écoles de la ville proposeront un repas végétarien deux fois par semaine. Enfin, le sport : l''équipe de basket de Villeurbanne a gagné hier soir quatre-vingt-cinq à soixante-dix-huit et jouera la finale samedi prochain."}]'::jsonb, '{"loai":"Bản tin radio","chu_de":"Ba tin ngắn lúc 8 giờ sáng.","y_chinh":["Giao thông: tai nạn trên cao tốc A6 gần Lyon, không ai bị thương, kẹt xe 10 km.","Giáo dục: từ tháng 9, căng tin trường có bữa chay hai lần mỗi tuần.","Thể thao: đội bóng rổ Villeurbanne thắng 85 78 và đá chung kết thứ bảy tới."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a2co10v4i05o', '[{"giong":"shimmer","chu":"Bonjour, c''est le service de livraison Rapido. Nous sommes passés chez vous ce matin vers onze heures pour livrer votre colis, mais vous étiez absent. Votre colis est maintenant disponible au point relais, la librairie Page Blanche, au quinze rue Gambetta. Vous pouvez le récupérer à partir de demain quatorze heures, pendant dix jours. N''oubliez pas votre pièce d''identité et le code reçu par SMS. Si vous préférez une nouvelle livraison, connectez-vous sur notre site et choisissez une date."}]'::jsonb, '{"loai":"Tin nhắn thoại của dịch vụ giao hàng","chu_de":"Giao hàng không gặp người nhận, bưu kiện chuyển đến điểm nhận.","y_chinh":["Sáng nay khoảng 11 h giao không gặp ai.","Bưu kiện ở hiệu sách Page Blanche, số 15 đường Gambetta, nhận từ 14 h ngày mai trong 10 ngày.","Mang giấy tờ tuỳ thân và mã SMS; hoặc chọn ngày giao lại trên trang web."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a2co09uyw05n', '[{"giong":"echo","chu":"Les nouvelles de votre ville. La nouvelle médiathèque a ouvert ses portes mardi dernier, dans l''ancienne gare. Plus de mille deux cents personnes l''ont déjà visitée cette semaine. On y trouve des livres, des films et un espace pour les enfants. Autre nouvelle : la course à pied du dimanche matin a réuni quatre cents coureurs, deux fois plus que l''année dernière. Enfin, la mairie a annoncé que le marché du centre-ville se tiendra désormais le mercredi et le samedi."}]'::jsonb, '{"loai":"Bản tin địa phương","chu_de":"Tin tức trong thành phố.","y_chinh":["Thư viện mới mở trong nhà ga cũ, hơn 1 200 người đã đến.","Giải chạy sáng chủ nhật có 400 người, gấp đôi năm ngoái.","Chợ trung tâm từ nay họp thứ tư và thứ bảy."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a2co08uts05m', '[{"giong":"nova","chu":"Voici la météo du week-end. Samedi, le soleil brillera sur tout le sud du pays, avec des températures jusqu''à vingt-huit degrés à Marseille. Dans le nord, en revanche, le ciel sera nuageux et il pleuvra l''après-midi, surtout à Lille. Dimanche, la pluie arrivera aussi en Bretagne, avec beaucoup de vent sur la côte. Les températures baisseront partout : on attend seulement quinze degrés à Paris. Bon week-end !"}]'::jsonb, '{"loai":"Bản tin thời tiết","chu_de":"Thời tiết cuối tuần trên cả nước.","y_chinh":["Thứ bảy: miền nam nắng, Marseille đến 28 độ; miền bắc nhiều mây, chiều mưa ở Lille.","Chủ nhật: mưa đến vùng Bretagne, gió mạnh ở bờ biển.","Nhiệt độ giảm khắp nơi, Paris chỉ 15 độ."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a2co07uoh05l', '[{"giong":"onyx","chu":"Bonjour madame Dupont, ici Julien Morel, du service des ressources humaines de la société Arcadia. Je vous appelle à propos de votre candidature pour le poste d''assistante commerciale. Nous aimerions vous rencontrer pour un entretien le jeudi douze octobre à dix heures. L''entretien durera environ quarante-cinq minutes. Merci d''apporter une copie de vos diplômes et une pièce d''identité. Pour confirmer, vous pouvez me rappeler au zéro quatre, soixante-dix-huit, trente-deux, quinze, zéro neuf, avant mardi. Bonne journée."}]'::jsonb, '{"loai":"Tin nhắn thoại công việc","chu_de":"Công ty Arcadia mời bà Dupont đi phỏng vấn.","y_chinh":["Phỏng vấn vị trí trợ lý kinh doanh thứ năm 12 tháng 10 lúc 10 h, khoảng 45 phút.","Mang bản sao bằng cấp và giấy tờ tuỳ thân.","Gọi lại để xác nhận trước thứ ba."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a2co06uhg05k', '[{"giong":"coral","chu":"Annonce un. Le train TER de dix heures douze à destination de Nantes partira avec un retard d''environ vingt minutes. Il partira de la voie B au lieu de la voie A."},{"giong":"onyx","chu":"Annonce deux. Chers clients, notre magasin fermera exceptionnellement à dix-neuf heures ce soir, pour inventaire. Demain, nous serons ouverts aux horaires habituels."},{"giong":"nova","chu":"Annonce trois. Les passagers du vol AF trois cent vingt pour Montréal sont priés de se présenter à la porte vingt-six. L''embarquement commencera dans dix minutes."},{"giong":"shimmer","chu":"Annonce quatre. La piscine municipale sera fermée pour travaux du lundi trois au dimanche neuf mars. Pendant cette période, vos cartes d''abonnement restent valables à la piscine du quartier Nord."}]'::jsonb, '{"loai":"Bốn thông báo nơi công cộng","chu_de":"Thông báo ở ga, cửa hàng, sân bay và bể bơi.","y_chinh":["Tàu TER 10 h 12 đi Nantes trễ khoảng 20 phút, đổi sang đường ray B.","Cửa hàng đóng lúc 19 h tối nay để kiểm kê.","Chuyến AF 320 đi Montréal: ra cửa 26, lên máy bay sau 10 phút.","Bể bơi đóng để sửa từ 3 đến 9 tháng 3; thẻ dùng được ở bể khu Bắc."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a2co05uce05j', '[{"giong":"echo","chu":"Mesdames et messieurs, bienvenue à bord du TGV numéro six mille deux cent quatorze à destination de Bordeaux. Nous arriverons à Bordeaux à quinze heures quarante, après un arrêt à Poitiers. La voiture-bar se trouve en voiture quatre ; elle est ouverte pendant tout le trajet. Nous vous rappelons que les grandes valises doivent être placées à l''entrée des voitures, et non dans le couloir. Pour votre confort, merci de mettre votre téléphone en mode silencieux. Bon voyage."}]'::jsonb, '{"loai":"Thông báo trên tàu","chu_de":"Lời chào và thông tin chuyến TGV đi Bordeaux.","y_chinh":["Tàu đến Bordeaux lúc 15 h 40, dừng ở Poitiers.","Toa quầy bar là toa số 4, mở suốt hành trình.","Vali lớn để ở đầu toa, không để ở lối đi; điện thoại để chế độ im lặng."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a2co04u6w05i', '[{"giong":"shimmer","chu":"Bonjour à tous ! La mairie vous informe : samedi vingt et un juin, c''est la Fête de la musique. Les concerts commenceront à dix-neuf heures sur la place de la République. En cas de pluie, ils auront lieu dans le gymnase du collège Victor-Hugo. L''entrée est gratuite, mais les places dans le gymnase sont limitées à trois cents personnes. Pensez à venir à pied ou à vélo : la rue principale sera fermée aux voitures à partir de dix-sept heures."}]'::jsonb, '{"loai":"Thông báo của toà thị chính","chu_de":"Lễ hội âm nhạc ngày 21 tháng 6.","y_chinh":["Hoà nhạc bắt đầu lúc 19 h ở quảng trường Cộng hoà.","Trời mưa thì chuyển vào nhà thi đấu trường Victor-Hugo, tối đa 300 chỗ.","Vào cửa miễn phí; phố chính cấm xe từ 17 h nên nên đi bộ hoặc xe đạp."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a2co03u1z05h', '[{"giong":"onyx","chu":"Chers visiteurs, le musée fermera ses portes dans trente minutes, à dix-huit heures. Les salles du deuxième étage sont déjà fermées. La boutique reste ouverte jusqu''à dix-huit heures quinze. Pour sortir, utilisez l''escalier principal : l''ascenseur est réservé aux personnes à mobilité réduite. Nous vous rappelons que votre billet est valable toute la journée de demain pour l''exposition temporaire. Merci de votre visite."}]'::jsonb, '{"loai":"Thông báo trong bảo tàng","chu_de":"Bảo tàng sắp đóng cửa.","y_chinh":["Bảo tàng đóng sau 30 phút, lúc 18 h; tầng hai đã đóng.","Cửa hàng lưu niệm mở đến 18 h 15.","Ra bằng cầu thang chính; vé dùng được cả ngày mai cho triển lãm tạm thời."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a2co02txs05g', '[{"giong":"nova","chu":"Chers clients, bienvenue dans votre magasin Bio Marché. Cette semaine, profitez de nos offres : pour deux paquets de café achetés, le troisième est offert. Au rayon fruits, les fraises sont à moins trente pour cent, seulement jusqu''à samedi. Attention, à partir de lundi prochain, le magasin ouvrira plus tôt, à huit heures, et fermera à vingt heures trente. Pour toute question, adressez-vous à l''accueil, près des caisses."}]'::jsonb, '{"loai":"Thông báo trong cửa hàng","chu_de":"Khuyến mãi tuần này và giờ mở cửa mới của Bio Marché.","y_chinh":["Mua hai gói cà phê được tặng gói thứ ba.","Dâu giảm 30 % đến thứ bảy.","Từ thứ hai tới, mở cửa lúc 8 h và đóng lúc 20 h 30."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a2co01ttd05f', '[{"giong":"coral","chu":"Mesdames et messieurs, en raison d''un incident technique, le trafic est interrompu sur la ligne quatre entre les stations Châtelet et Porte d''Orléans. La reprise du trafic est prévue vers dix-sept heures trente. Pour continuer votre trajet, nous vous conseillons de prendre la ligne quatorze ou les bus de remplacement, devant la sortie numéro deux. Nous vous prions de nous excuser pour la gêne occasionnée."}]'::jsonb, '{"loai":"Thông báo ở ga tàu điện ngầm","chu_de":"Tuyến số 4 ngừng chạy vì sự cố kỹ thuật.","y_chinh":["Tuyến 4 dừng giữa ga Châtelet và Porte d''Orléans.","Dự kiến chạy lại khoảng 17 h 30.","Đi tuyến 14 hoặc xe buýt thay thế trước lối ra số 2."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a1co29t0906a', '[{"giong":"nova","chu":"Bonjour Alex. Demain, on fait un pique-nique au parc. Apporte une couverture, des verres et des fruits. Je prends les sandwichs et le gâteau. Pas besoin de chaises. S''il fait beau, prends ton ballon."}]'::jsonb, '{"loai":"Tin nhắn thoại của bạn bè","chu_de":"Chuẩn bị đồ cho buổi dã ngoại ở công viên.","y_chinh":["Alex mang khăn trải, cốc và trái cây.","Người gọi mang bánh mì kẹp và bánh ngọt; không cần ghế.","Nếu trời đẹp thì mang bóng."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a1co28qhp069', '[{"giong":"shimmer","chu":"Salut Chloé ! Voici ma nouvelle chambre. Il y a un lit, un bureau et une petite lampe. Il y a aussi une armoire. Je n''ai pas de télévision, mais j''ai une grande fenêtre."}]'::jsonb, '{"loai":"Lời giới thiệu ngắn","chu_de":"Một người tả căn phòng mới của mình.","y_chinh":["Trong phòng có giường, bàn học, đèn nhỏ và tủ quần áo.","Không có ti vi.","Có một cửa sổ lớn."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a1co27odt068', '[{"giong":"coral","chu":"Chéri, pour ce soir, achète du lait, des œufs et du fromage, s''il te plaît. Il ne faut pas de pain, j''ai une baguette. Prends aussi des pommes. On a déjà de l''eau."}]'::jsonb, '{"loai":"Tin nhắn trong gia đình","chu_de":"Danh sách đồ cần mua cho tối nay.","y_chinh":["Cần mua sữa, trứng, phô mai và táo.","Không cần bánh mì vì đã có baguette.","Không cần nước vì nhà còn."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a1co26m0o067', '[{"giong":"onyx","chu":"Bonjour à tous. Demain, pour le cours, apportez un cahier, un stylo bleu et votre livre de français. Vous n''avez pas besoin de votre ordinateur. Prenez aussi une règle, s''il vous plaît."}]'::jsonb, '{"loai":"Lời dặn của giáo viên","chu_de":"Đồ cần mang cho buổi học ngày mai.","y_chinh":["Mang vở, bút xanh, sách tiếng Pháp và thước kẻ.","Không cần máy tính."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a1co25jk6066', '[{"giong":"nova","chu":"Salut Lucas ! Pour les vacances à la montagne, n''oublie pas ton manteau et tes chaussures de marche. Prends aussi ton appareil photo. Tu n''as pas besoin de maillot de bain. Et prends ton passeport, on va en Suisse !"}]'::jsonb, '{"loai":"Tin nhắn thoại của bạn bè","chu_de":"Chuẩn bị hành lý đi nghỉ ở vùng núi Thuỵ Sĩ.","y_chinh":["Mang áo khoác, giày đi bộ và máy ảnh.","Không cần đồ bơi.","Phải mang hộ chiếu vì sang Thuỵ Sĩ."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a1co24h3x065', '[{"giong":"alloy","chu":"Dialogue un."},{"giong":"echo","chu":"Je voudrais changer cent euros."},{"giong":"shimmer","chu":"Vous avez votre passeport ?"},{"giong":"alloy","chu":"Dialogue deux."},{"giong":"nova","chu":"Une chambre pour deux nuits, s''il vous plaît."},{"giong":"onyx","chu":"Votre nom, madame ?"},{"giong":"alloy","chu":"Dialogue trois."},{"giong":"coral","chu":"Les cheveux courts, s''il vous plaît."},{"giong":"echo","chu":"Très bien, asseyez-vous."},{"giong":"alloy","chu":"Dialogue quatre."},{"giong":"onyx","chu":"Un café et un croissant, s''il vous plaît."},{"giong":"nova","chu":"Sur place ou à emporter ?"}]'::jsonb, '{"loai":"Bốn đoạn hội thoại ngắn","chu_de":"Bốn dịch vụ thường gặp.","y_chinh":["Hội thoại 1: đổi tiền, cần hộ chiếu.","Hội thoại 2: đặt phòng khách sạn hai đêm.","Hội thoại 3: cắt tóc ngắn ở tiệm.","Hội thoại 4: gọi cà phê và bánh sừng bò ở quán."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a1co23fap064', '[{"giong":"alloy","chu":"Dialogue un."},{"giong":"coral","chu":"On mange quoi ce soir ?"},{"giong":"onyx","chu":"Des pâtes. Tu mets la table, s''il te plaît ?"},{"giong":"alloy","chu":"Dialogue deux."},{"giong":"nova","chu":"Tu fais du sport ce week-end ?"},{"giong":"echo","chu":"Oui, je joue au foot dimanche matin."},{"giong":"alloy","chu":"Dialogue trois."},{"giong":"shimmer","chu":"Bonjour, je voudrais envoyer ce colis en France."},{"giong":"onyx","chu":"Bien sûr. Il pèse deux kilos."},{"giong":"alloy","chu":"Dialogue quatre."},{"giong":"echo","chu":"Deux places pour le film de vingt heures, s''il vous plaît."},{"giong":"coral","chu":"Salle cinq. Bon film !"}]'::jsonb, '{"loai":"Bốn đoạn hội thoại ngắn","chu_de":"Sinh hoạt ở nhà và cuối tuần.","y_chinh":["Hội thoại 1: hỏi tối nay ăn gì, nhờ dọn bàn.","Hội thoại 2: nói về chơi bóng đá sáng chủ nhật.","Hội thoại 3: gửi bưu kiện ở bưu điện.","Hội thoại 4: mua vé xem phim lúc 20 h."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a1co22do8063', '[{"giong":"alloy","chu":"Dialogue un."},{"giong":"onyx","chu":"Qu''est-ce qui ne va pas ?"},{"giong":"coral","chu":"J''ai mal à la tête et j''ai de la fièvre."},{"giong":"alloy","chu":"Dialogue deux."},{"giong":"shimmer","chu":"Ouvrez votre livre à la page dix."},{"giong":"echo","chu":"Madame, je n''ai pas mon livre."},{"giong":"alloy","chu":"Dialogue trois."},{"giong":"nova","chu":"Salut ! Ça va ? Tu vas où ?"},{"giong":"echo","chu":"Salut ! Je vais à la piscine. Tu viens ?"},{"giong":"alloy","chu":"Dialogue quatre."},{"giong":"coral","chu":"Bonjour, je voudrais des médicaments pour la gorge."},{"giong":"onyx","chu":"Voici. Trois fois par jour."}]'::jsonb, '{"loai":"Bốn đoạn hội thoại ngắn","chu_de":"Tình huống ở phòng khám, lớp học, ngoài phố và nhà thuốc.","y_chinh":["Hội thoại 1: khám bệnh vì đau đầu, sốt.","Hội thoại 2: trong lớp, một học sinh quên sách.","Hội thoại 3: hai bạn gặp nhau, rủ đi bể bơi.","Hội thoại 4: mua thuốc đau họng, uống ba lần một ngày."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a1co21bsc062', '[{"giong":"alloy","chu":"Dialogue un."},{"giong":"shimmer","chu":"Un aller simple pour Lyon, s''il vous plaît."},{"giong":"onyx","chu":"Ça fait quarante euros."},{"giong":"alloy","chu":"Dialogue deux."},{"giong":"echo","chu":"Pardon, ce bus va à la mairie ?"},{"giong":"nova","chu":"Oui, c''est le quatrième arrêt."},{"giong":"alloy","chu":"Dialogue trois."},{"giong":"coral","chu":"Bonjour, à l''aéroport, s''il vous plaît."},{"giong":"onyx","chu":"Très bien. Vous avez des valises ?"},{"giong":"alloy","chu":"Dialogue quatre."},{"giong":"echo","chu":"Excusez-moi, la rue Molière, s''il vous plaît ?"},{"giong":"shimmer","chu":"C''est tout droit, puis à gauche."}]'::jsonb, '{"loai":"Bốn đoạn hội thoại ngắn","chu_de":"Hỏi đường và đi lại bằng tàu, xe buýt, taxi.","y_chinh":["Hội thoại 1: mua vé tàu một chiều đi Lyon, 40 euro.","Hội thoại 2: hỏi xe buýt có đến toà thị chính không.","Hội thoại 3: đi taxi ra sân bay.","Hội thoại 4: hỏi đường đến phố Molière."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a1co209vz061', '[{"giong":"alloy","chu":"Dialogue un."},{"giong":"nova","chu":"Vous avez choisi ?"},{"giong":"onyx","chu":"Oui, je voudrais le poulet et une carafe d''eau."},{"giong":"alloy","chu":"Dialogue deux."},{"giong":"shimmer","chu":"Je cherche un pantalon noir."},{"giong":"echo","chu":"Quelle taille, madame ?"},{"giong":"alloy","chu":"Dialogue trois."},{"giong":"onyx","chu":"Bonjour, deux baguettes, s''il vous plaît."},{"giong":"coral","chu":"Voilà. Deux euros quarante."},{"giong":"alloy","chu":"Dialogue quatre."},{"giong":"coral","chu":"Un kilo de tomates, c''est combien ?"},{"giong":"echo","chu":"Trois euros le kilo. Elles sont très bonnes !"}]'::jsonb, '{"loai":"Bốn đoạn hội thoại ngắn","chu_de":"Gọi món và mua hàng.","y_chinh":["Hội thoại 1: gọi món ở nhà hàng.","Hội thoại 2: tìm mua quần ở cửa hàng quần áo.","Hội thoại 3: mua bánh mì ở tiệm bánh.","Hội thoại 4: hỏi giá cà chua ở chợ."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a1co194c5060', '[{"giong":"coral","chu":"Annonce un. Dans le bus numéro sept, le prochain arrêt est la mairie. Descendez ici pour aller au musée."},{"giong":"onyx","chu":"Annonce deux. Les élèves de la classe de français vont à la salle vingt. Le cours commence à quatorze heures."},{"giong":"nova","chu":"Annonce trois. À la bibliothèque, il est dix-sept heures cinquante. La bibliothèque ferme à dix-huit heures. Merci de rendre vos livres à l''accueil."}]'::jsonb, '{"loai":"Ba thông báo nơi công cộng","chu_de":"Thông báo trên xe buýt, ở trường và ở thư viện.","y_chinh":["Xe buýt số 7: trạm tới là toà thị chính, xuống đây để đi bảo tàng.","Lớp tiếng Pháp học ở phòng 20, bắt đầu lúc 14 h.","Thư viện đóng lúc 18 h, trả sách ở quầy tiếp đón."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a1co1826d05z', '[{"giong":"shimmer","chu":"Madame, monsieur, bonjour. Le vol pour Hanoï part à vingt-trois heures. Les passagers vont à la porte douze. Préparez votre passeport et votre carte d''embarquement. Merci et bon voyage."}]'::jsonb, '{"loai":"Thông báo ở sân bay","chu_de":"Chuyến bay đi Hà Nội chuẩn bị lên máy bay.","y_chinh":["Máy bay cất cánh lúc 23 h.","Hành khách đến cửa số 12.","Chuẩn bị hộ chiếu và thẻ lên máy bay."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a1co17zmx05y', '[{"giong":"onyx","chu":"Mesdames et messieurs, la piscine ferme dans quinze minutes. Merci de sortir de l''eau à dix-huit heures quarante-cinq. Les douches sont à gauche. La piscine ouvre demain à neuf heures. Bonne soirée."}]'::jsonb, '{"loai":"Thông báo ở bể bơi","chu_de":"Bể bơi sắp đóng cửa.","y_chinh":["Bể đóng sau 15 phút, ra khỏi nước lúc 18 h 45.","Phòng tắm ở bên trái.","Ngày mai mở cửa lúc 9 h."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a1co16x5p05x', '[{"giong":"nova","chu":"Bonjour à tous. Aujourd''hui, les pommes sont à deux euros le kilo au rayon fruits. Le magasin ferme à vingt heures. La caisse numéro trois est fermée. Merci et bonnes courses !"}]'::jsonb, '{"loai":"Thông báo trong siêu thị","chu_de":"Thông tin trong ngày ở siêu thị.","y_chinh":["Táo giá 2 euro một ký ở quầy trái cây.","Siêu thị đóng cửa lúc 20 h.","Quầy thu ngân số 3 đóng."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a1co15v5x05w', '[{"giong":"coral","chu":"Attention, s''il vous plaît. Le train numéro huit cent douze pour Marseille part de la voie quatre à quatorze heures dix. Il a dix minutes de retard. Merci de votre attention."}]'::jsonb, '{"loai":"Thông báo ở nhà ga","chu_de":"Thông tin chuyến tàu đi Marseille.","y_chinh":["Tàu số 812 chạy từ đường ray số 4.","Giờ khởi hành 14 h 10.","Tàu trễ 10 phút."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a1co14swl05v', '[{"giong":"nova","chu":"Message un. Bonjour, c''est Nadia. Le cours de yoga de lundi est annulé. Le prochain cours, c''est mercredi à dix-huit heures."},{"giong":"onyx","chu":"Message deux. Salut, c''est Marc. Je suis à la gare. Mon train a une heure de retard. J''arrive à vingt-deux heures."},{"giong":"shimmer","chu":"Message trois. Bonjour, ici la bibliothèque. Votre livre est arrivé. Vous pouvez venir le chercher jusqu''à samedi."}]'::jsonb, '{"loai":"Ba tin nhắn thoại","chu_de":"Ba tin báo thay đổi trong đời sống hằng ngày.","y_chinh":["Tin 1: lớp yoga thứ hai bị huỷ, buổi sau là thứ tư lúc 18 h.","Tin 2: tàu của Marc trễ một giờ, anh đến lúc 22 h.","Tin 3: thư viện báo sách đã về, lấy trước thứ bảy."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a1co13qu205u', '[{"giong":"coral","chu":"Tom, c''est maman. Je rentre tard ce soir. Va chercher ta sœur à l''école à seize heures trente, s''il te plaît. Il y a du poulet dans le frigo. Et achète du pain à la boulangerie. Merci, mon chéri !"}]'::jsonb, '{"loai":"Tin nhắn thoại trong gia đình","chu_de":"Mẹ nhờ Tom làm vài việc vì về muộn.","y_chinh":["Đón em gái ở trường lúc 16 h 30.","Trong tủ lạnh có thịt gà cho bữa tối.","Mua bánh mì ở tiệm."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a1co12oc305t', '[{"giong":"shimmer","chu":"Coucou Sarah, c''est Emma ! Samedi, c''est mon anniversaire. J''ai vingt ans. Je t''invite chez moi à dix-neuf heures, au douze, rue Victor-Hugo. Tu peux apporter un gâteau ? Je fais les boissons. Bisous !"}]'::jsonb, '{"loai":"Tin nhắn thoại của bạn bè","chu_de":"Emma mời Sarah dự sinh nhật 20 tuổi.","y_chinh":["Tiệc thứ bảy lúc 19 h, tại số 12 đường Victor-Hugo.","Emma nhờ Sarah mang bánh ngọt.","Emma lo phần đồ uống."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a1co11lvu05s', '[{"giong":"onyx","chu":"Bonjour Julie, c''est Paul. Pour le dîner de vendredi, il y a un changement. Je travaille tard. On ne mange pas à dix-neuf heures, mais à vingt heures trente. C''est toujours au restaurant italien. Merci, à vendredi !"}]'::jsonb, '{"loai":"Tin nhắn thoại","chu_de":"Paul báo đổi giờ ăn tối thứ sáu.","y_chinh":["Paul làm việc muộn.","Bữa tối dời từ 19 h sang 20 h 30.","Địa điểm không đổi: nhà hàng Ý."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a1co10jna05r', '[{"giong":"nova","chu":"Salut Antoine, c''est Léa. Tu es libre demain ? On peut se voir au café de la gare à seize heures. Après, on peut aller au parc. Appelle-moi ce soir. À demain !"}]'::jsonb, '{"loai":"Tin nhắn thoại của bạn bè","chu_de":"Léa rủ Antoine gặp nhau ngày mai.","y_chinh":["Gặp ở quán cà phê nhà ga lúc 16 h.","Sau đó có thể đi công viên.","Léa dặn gọi lại tối nay."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a1co08fof05p', '[{"giong":"onyx","chu":"Bonjour madame. Votre commande est prête. Nous sommes au vingt-huit, rue de la Paix. Le magasin est ouvert du mardi au samedi, de dix heures à dix-neuf heures. Le prix total est de soixante-quatorze euros. Vous pouvez aussi nous appeler au zéro un, quarante-deux, quinze, quatre-vingt-huit, trente."}]'::jsonb, '{"loai":"Tin nhắn thoại của cửa hàng","chu_de":"Cửa hàng báo đơn hàng đã sẵn sàng.","y_chinh":["Địa chỉ: số 28 đường de la Paix.","Mở từ thứ ba đến thứ bảy, 10 h đến 19 h.","Tổng tiền 74 euro; có số điện thoại để gọi."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('a1co07cm205o', '[{"giong":"shimmer","chu":"Bonjour, c''est Marie. On va au cinéma samedi. Le film commence à vingt heures quinze. Le ticket coûte neuf euros cinquante. Je t''attends devant la salle quatre à dix-neuf heures quarante-cinq. Mon nouveau numéro, c''est le zéro six, trente, vingt-deux, soixante-dix, quatorze. Au revoir !"}]'::jsonb, '{"loai":"Tin nhắn thoại của bạn bè","chu_de":"Marie hẹn đi xem phim thứ bảy.","y_chinh":["Phim bắt đầu lúc 20 h 15, vé 9,50 euro.","Gặp trước phòng chiếu số 4 lúc 19 h 45.","Marie đọc số điện thoại mới theo từng cặp số."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('nhapmur5hnlp029', '[{"giong":"ash","chu":"Bienvenue dans « Futurs ». L''intelligence artificielle générative s''installe dans les bureaux : rédaction de courriels, résumés de réunions, traduction. Va-t-elle supprimer des emplois ? Nous recevons Claire Dubois, économiste du travail. Claire, faut-il avoir peur ?"},{"giong":"nova","chu":"Il faut surtout éviter deux erreurs : croire que rien ne va changer, et croire que tout va disparaître. Les études récentes montrent que l''IA remplace rarement un métier entier. Elle remplace des tâches. Un comptable, par exemple, passera moins de temps à saisir des données et davantage à conseiller ses clients. Le métier se transforme plus qu''il ne disparaît."},{"giong":"ash","chu":"Mais certains postes sont quand même menacés ?"},{"giong":"nova","chu":"Oui, et il ne faut pas le nier. Les emplois très répétitifs et peu qualifiés dans les services administratifs sont les plus exposés, et ce sont souvent des emplois occupés par des femmes. Paradoxalement, des métiers qualifiés comme traducteur ou rédacteur sont aussi touchés, alors qu''on les pensait protégés. En revanche, les métiers qui demandent un contact humain, de la dextérité ou un jugement en situation, comme infirmier, électricien ou enseignant, sont beaucoup moins concernés."},{"giong":"ash","chu":"Comment les salariés peuvent-ils s''y préparer ?"},{"giong":"nova","chu":"Par la formation, évidemment, mais pas seulement la formation technique. Savoir formuler une demande à un outil, c''est utile, mais savoir vérifier ce qu''il produit l''est encore plus. Ces outils se trompent avec beaucoup d''assurance. L''esprit critique devient une compétence professionnelle à part entière."},{"giong":"ash","chu":"Et les entreprises ?"},{"giong":"nova","chu":"Elles ont une responsabilité. Les gains de productivité peuvent servir à réduire les effectifs, ou bien à libérer du temps pour des tâches plus intéressantes, voire à réduire le temps de travail. C''est un choix, pas une fatalité technologique. Et ce choix devrait se discuter avec les salariés et leurs représentants, pas être décidé seul par la direction."}]'::jsonb, '{"loai":"Phỏng vấn radio với chuyên gia","chu_de":"Trí tuệ nhân tạo tạo sinh và việc làm.","y_chinh":["AI ít khi thay cả một nghề, mà thay từng việc; nghề biến đổi nhiều hơn là biến mất.","Việc lặp lại, ít chuyên môn dễ bị ảnh hưởng nhất, cả dịch giả, biên tập viên; nghề cần tiếp xúc con người, khéo tay hay phán đoán thì ít bị ảnh hưởng.","Cần đào tạo tư duy phản biện để kiểm tra kết quả của công cụ.","Doanh nghiệp có trách nhiệm chọn dùng năng suất tăng thêm để cắt người hay giảm giờ làm, và nên bàn với người lao động."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('nhapmur5gsn4026', '[{"giong":"ash","chu":"Dans « Ils l''ont fait », nous rencontrons aujourd''hui Lucie, vingt et un ans, qui est partie seule pendant trois mois en Amérique du Sud. Lucie, pourquoi ce voyage ?"},{"giong":"nova","chu":"Après ma licence de géographie, je ne savais pas quoi faire ensuite. Je voulais prendre du temps pour réfléchir, et aussi améliorer mon espagnol. J''ai travaillé tout l''été dans un camping pour économiser deux mille cinq cents euros."},{"giong":"ash","chu":"Trois mois avec deux mille cinq cents euros, c''est possible ?"},{"giong":"nova","chu":"Oui, si on fait attention. Je dormais dans des auberges de jeunesse ou chez l''habitant, et je prenais le bus, jamais l''avion sur place. Et pendant un mois, j''ai fait du volontariat dans une ferme au Pérou : je travaillais quatre heures par jour, et en échange, j''étais logée et nourrie."},{"giong":"ash","chu":"Vos parents n''avaient pas peur ?"},{"giong":"nova","chu":"Ma mère, si, beaucoup ! Alors on a fixé une règle : je lui envoyais un message tous les soirs. Et je lui partageais ma position. Honnêtement, je me suis toujours sentie en sécurité, sauf une fois, à Lima, quand on m''a volé mon téléphone dans un marché."},{"giong":"ash","chu":"Qu''est-ce que ce voyage vous a apporté ?"},{"giong":"nova","chu":"De la confiance en moi, surtout. Quand on doit tout organiser seule, dans une autre langue, on découvre qu''on est capable de beaucoup de choses. Et j''ai trouvé ma voie : en rentrant, je me suis inscrite en master de tourisme durable."},{"giong":"ash","chu":"Un conseil pour ceux qui veulent partir ?"},{"giong":"nova","chu":"Ne pas tout planifier. Gardez des jours libres : les meilleurs moments, ce sont souvent ceux qu''on n''a pas prévus."}]'::jsonb, '{"loai":"Phỏng vấn radio","chu_de":"Lucie, 21 tuổi, đi một mình ba tháng ở Nam Mỹ.","y_chinh":["Sau bằng cử nhân, cô muốn có thời gian suy nghĩ và học tiếng Tây Ban Nha; làm cả mùa hè để dành 2 500 euro.","Cô tiết kiệm bằng nhà trọ, đi xe buýt và làm tình nguyện ở trang trại để được ăn ở.","Mẹ lo nên cô nhắn tin mỗi tối; chỉ một lần bị trộm điện thoại ở Lima.","Chuyến đi cho cô sự tự tin và định hướng học thạc sĩ du lịch bền vững; lời khuyên là đừng lên kế hoạch kín hết."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('nhapmur5gog2025', '[{"giong":"sage","chu":"Chronique « Consommer mieux ». Saviez-vous qu''en France, chaque habitant jette en moyenne trente kilos de nourriture par an, dont sept kilos de produits encore emballés ? Le gaspillage alimentaire ne se passe pas seulement dans les supermarchés : près de la moitié a lieu à la maison. Alors, comment faire mieux ? Voici cinq conseils simples."},{"giong":"sage","chu":"Premier conseil : faites une liste avant d''aller faire les courses, et regardez d''abord ce qu''il reste dans votre réfrigérateur. C''est la meilleure façon d''éviter d''acheter deux fois la même chose."},{"giong":"sage","chu":"Deuxième conseil : comprenez les dates. La mention « à consommer jusqu''au » concerne les produits frais comme la viande ou le poisson : après cette date, il ne faut plus les manger. En revanche, « à consommer de préférence avant » concerne les pâtes, le riz ou les biscuits : après la date, le produit peut perdre un peu de goût, mais il ne présente pas de danger."},{"giong":"sage","chu":"Troisième conseil : rangez bien votre réfrigérateur. Placez devant les produits qui doivent être mangés en premier. Quatrième conseil : cuisinez les restes. Un reste de légumes devient une soupe, du pain sec devient un pain perdu. Enfin, cinquième conseil : utilisez les applications anti-gaspillage. Elles permettent d''acheter à petit prix, souvent moins de cinq euros, des paniers d''invendus dans les boulangeries et les restaurants du quartier."},{"giong":"sage","chu":"Selon une association de consommateurs, une famille de quatre personnes peut économiser jusqu''à quatre cents euros par an en suivant ces conseils. Bon pour la planète, et bon pour le porte-monnaie !"}]'::jsonb, '{"loai":"Chuyên mục radio","chu_de":"Năm lời khuyên chống lãng phí thực phẩm.","y_chinh":["Mỗi người Pháp bỏ khoảng 30 kg thức ăn mỗi năm, gần một nửa lãng phí xảy ra ở nhà.","Lập danh sách đi chợ và hiểu hai loại hạn dùng: « à consommer jusqu''au » (bắt buộc) và « de préférence avant » (chỉ giảm vị).","Xếp tủ lạnh hợp lý, nấu lại đồ thừa, dùng ứng dụng mua hàng ế giá rẻ.","Một gia đình bốn người có thể tiết kiệm đến 400 euro mỗi năm."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('nhapmur5gjk6024', '[{"giong":"coral","chu":"Bonjour à tous et bienvenue dans « Vie pro ». Aujourd''hui, nous parlons de la semaine de quatre jours. Avec nous, Nadia Benali, directrice d''une entreprise de quarante salariés à Nantes, qui l''a adoptée il y a un an. Nadia, pourquoi ce choix ?"},{"giong":"shimmer","chu":"Bonjour. Au départ, nous avions un vrai problème de recrutement : sur certains postes, nous ne recevions presque aucune candidature. Nous avons cherché un avantage que les grandes entreprises n''offraient pas. La semaine de quatre jours nous a semblé une bonne idée."},{"giong":"coral","chu":"Concrètement, comment ça fonctionne ? Les salariés travaillent moins ?"},{"giong":"shimmer","chu":"Non, et c''est important de le préciser. Ils font toujours trente-cinq heures, mais sur quatre jours au lieu de cinq. Les journées sont donc un peu plus longues, de huit heures trente à dix-sept heures quarante-cinq. Chacun choisit son jour de repos, le lundi ou le vendredi, en accord avec son équipe."},{"giong":"coral","chu":"Et après un an, quel bilan ?"},{"giong":"shimmer","chu":"Plutôt positif. Les arrêts maladie ont baissé d''environ vingt pour cent, et nous avons reçu trois fois plus de candidatures qu''avant. Les salariés disent qu''ils ont plus de temps pour leur famille et pour leurs démarches administratives."},{"giong":"coral","chu":"Il y a quand même des difficultés ?"},{"giong":"shimmer","chu":"Oui, bien sûr. Les journées longues fatiguent certains salariés, surtout ceux qui ont beaucoup de transport. Et pour nos clients, il a fallu s''organiser : le service client reste ouvert cinq jours sur cinq, grâce à un système de roulement. Deux personnes ont d''ailleurs préféré revenir à la semaine de cinq jours, et nous l''avons accepté."},{"giong":"coral","chu":"Un conseil pour les entreprises qui hésitent ?"},{"giong":"shimmer","chu":"Faire un test de six mois, et surtout demander l''avis des salariés avant de commencer. Ce n''est pas une solution magique, mais chez nous, ça a changé l''ambiance."}]'::jsonb, '{"loai":"Phỏng vấn radio","chu_de":"Một doanh nghiệp ở Nantes áp dụng tuần làm bốn ngày.","y_chinh":["Lý do: khó tuyển người, cần một lợi thế mà công ty lớn không có.","Vẫn 35 giờ nhưng dồn vào bốn ngày; mỗi người chọn nghỉ thứ hai hoặc thứ sáu.","Sau một năm: nghỉ ốm giảm khoảng 20 %, hồ sơ ứng tuyển tăng gấp ba.","Khó khăn: ngày dài gây mệt, phải xếp ca để phục vụ khách; lời khuyên là thử sáu tháng và hỏi ý nhân viên."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('nhapmur36y4201b', '[{"giong":"coral","chu":"Bonjour, nous faisons une enquête : avez-vous déjà essayé d''arrêter de fumer ?"},{"giong":"onyx","chu":"Oui, trois fois. La dernière fois, j''ai tenu six mois, et puis j''ai recommencé pendant une période de stress au travail. Le plus dur, c''est le café du matin sans cigarette."},{"giong":"nova","chu":"Moi, j''ai arrêté il y a deux ans, quand j''étais enceinte. J''ai utilisé des patchs, et j''ai économisé presque deux cents euros par mois. Avec cet argent, on est partis en vacances !"},{"giong":"verse","chu":"Je n''ai jamais fumé de cigarettes, mais beaucoup de mes amis vapotent. Ils pensent que ce n''est pas dangereux. Moi, je ne suis pas sûr."}]'::jsonb, '{"loai":"Phỏng vấn ngoài phố (ba người)","chu_de":"Kinh nghiệm bỏ thuốc lá.","y_chinh":["Người 1 đã thử bỏ ba lần, lần gần nhất giữ được sáu tháng rồi hút lại vì căng thẳng; khó nhất là ly cà phê buổi sáng.","Người 2 bỏ được hai năm khi mang thai, nhờ miếng dán; tiết kiệm gần 200 euro mỗi tháng để đi nghỉ.","Người 3 chưa từng hút, nhưng nghi ngờ thuốc lá điện tử mà bạn bè cho là vô hại."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('nhapmur36rma01a', '[{"giong":"sage","chu":"Vous avez sûrement déjà reçu ce genre de message : « Partagez vite, le gouvernement va interdire les voitures à essence dès l''année prochaine ! » Avant de partager, prenez trente secondes. D''abord, regardez la source : est-ce un média connu, ou une page que personne ne connaît ? Ensuite, vérifiez la date : beaucoup de fausses informations sont en réalité de vieilles nouvelles sorties de leur contexte. Troisième réflexe : cherchez la même information sur deux autres sites sérieux. Si vous ne la trouvez nulle part ailleurs, méfiez-vous. Enfin, attention aux titres qui provoquent la peur ou la colère : ils sont faits pour être partagés, pas pour informer. Et vous, avez-vous déjà partagé une fausse information sans le savoir ?"}]'::jsonb, '{"loai":"Chuyên mục radio","chu_de":"Cách kiểm tra một thông tin trước khi chia sẻ.","y_chinh":["Xem nguồn tin: báo có tên tuổi hay trang không ai biết.","Xem ngày đăng: nhiều tin giả là tin cũ bị tách khỏi bối cảnh.","Tìm cùng tin đó trên hai trang nghiêm túc khác; cảnh giác với tiêu đề gây sợ hãi hoặc giận dữ."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('nhapmur36fu4019', '[{"giong":"coral","chu":"Aujourd''hui, nous recevons Karim, vingt-quatre ans, bénévole aux Restos du quartier. Karim, depuis quand faites-vous du bénévolat ?"},{"giong":"echo","chu":"Depuis trois ans. Au début, j''étais étudiant et j''avais du temps libre le samedi. Une amie m''a proposé de venir aider à la distribution des repas, et je ne suis jamais reparti."},{"giong":"coral","chu":"Concrètement, que faites-vous ?"},{"giong":"echo","chu":"Le samedi matin, je trie les produits que nous donnent les supermarchés. L''après-midi, je sers les repas. Mais le plus important, pour moi, c''est de discuter avec les gens. Beaucoup de personnes âgées viennent surtout pour parler, pas seulement pour manger."},{"giong":"coral","chu":"Qu''est-ce que le bénévolat vous a apporté ?"},{"giong":"echo","chu":"De la patience, d''abord. Et puis, ça m''a aidé à trouver du travail : j''ai mis cette expérience sur mon CV, et mon employeur actuel m''a dit que c''était ce qui l''avait convaincu."},{"giong":"coral","chu":"Un conseil pour les jeunes qui hésitent ?"},{"giong":"echo","chu":"Commencez par deux heures par mois. On n''a pas besoin de donner tout son temps pour être utile."}]'::jsonb, '{"loai":"Phỏng vấn radio","chu_de":"Karim, 24 tuổi, kể về việc làm tình nguyện ở bếp ăn khu phố.","y_chinh":["Anh làm ba năm, bắt đầu khi còn là sinh viên, nhờ một người bạn rủ.","Sáng thứ bảy phân loại thực phẩm, chiều phát suất ăn; quan trọng nhất là trò chuyện với người già.","Việc tình nguyện giúp anh kiên nhẫn hơn và có việc làm nhờ ghi vào CV.","Lời khuyên: bắt đầu với hai giờ mỗi tháng."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('nhapmur3635v018', '[{"giong":"ash","chu":"Service client de MaBoutique, bonjour, Thomas à votre écoute."},{"giong":"shimmer","chu":"Bonjour. J''ai commandé une paire de chaussures il y a deux semaines, et je n''ai toujours rien reçu. Pourtant, on m''avait promis une livraison en trois jours."},{"giong":"ash","chu":"Je suis désolé. Vous avez votre numéro de commande ?"},{"giong":"shimmer","chu":"Oui, c''est le 4-7-8-2-1."},{"giong":"ash","chu":"Merci. Je vois que le colis est bloqué au centre de tri depuis dix jours, à cause d''une adresse incomplète : il manque le numéro de l''appartement."},{"giong":"shimmer","chu":"Ah, je ne savais pas. Qu''est-ce qu''on peut faire ?"},{"giong":"ash","chu":"Je corrige l''adresse tout de suite, et le colis vous sera livré d''ici vendredi. Pour nous excuser, nous vous remboursons les frais de livraison, soit six euros quatre-vingt-dix."},{"giong":"shimmer","chu":"C''est gentil, merci. Et si les chaussures ne me vont pas ?"},{"giong":"ash","chu":"Vous avez trente jours pour les retourner gratuitement."}]'::jsonb, '{"loai":"Cuộc gọi tới tổng đài chăm sóc khách hàng","chu_de":"Khách hỏi vì sao đôi giày đặt hai tuần chưa tới.","y_chinh":["Hàng hứa giao trong ba ngày nhưng đã hai tuần.","Bưu kiện kẹt ở trung tâm phân loại vì địa chỉ thiếu số căn hộ.","Nhân viên sửa địa chỉ, giao trước thứ sáu, hoàn 6,90 euro phí giao; được đổi trả miễn phí trong 30 ngày."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('nhapmur351gr014', '[{"giong":"onyx","chu":"Attention, information pour tous les élèves. À partir de lundi, la cantine ouvre à onze heures trente, et non à midi. La bibliothèque est fermée mercredi après-midi. Les cours de sport ont lieu au gymnase, rue Victor-Hugo, et pas au stade. Merci !"}]'::jsonb, '{"loai":"Thông báo ở trường","chu_de":"Thay đổi giờ giấc và địa điểm trong trường từ thứ hai.","y_chinh":["Căng tin mở lúc 11 h 30 thay vì 12 h.","Thư viện đóng cửa chiều thứ tư.","Giờ thể dục học ở nhà thi đấu đường Victor-Hugo, không ở sân vận động."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
insert into public.loi_nghe (exercise_id, loi, phan_tich) values ('nhapmur34xv8013', '[{"giong":"nova","chu":"Bonjour, c''est Sophie, de la salle de sport Forme Plus. Vous avez demandé des informations sur nos cours. Le cours de yoga a lieu le mardi et le jeudi, à dix-huit heures. Le cours de natation, c''est le samedi matin, à neuf heures. L''abonnement coûte vingt-cinq euros par mois. Pour l''inscription, apportez une photo et un certificat médical. Notre numéro : le 04 56 32 18 90. À bientôt !"}]'::jsonb, '{"loai":"Tin nhắn thoại","chu_de":"Phòng tập Forme Plus trả lời người hỏi về các lớp.","y_chinh":["Yoga thứ ba và thứ năm lúc 18 h; bơi sáng thứ bảy lúc 9 h.","Phí 25 euro một tháng.","Đăng ký cần ảnh và giấy chứng nhận sức khoẻ; có số điện thoại để gọi lại."]}'::jsonb) on conflict (exercise_id) do update set loi = excluded.loi, phan_tich = excluded.phan_tich, cap_nhat = now();
