-- 195 · NẠP LỜI NGHE VÀ PHÂN TÍCH CHO 74 BÀI NGHE LUYỆN TẬP (lô 40, 04/11).
--
-- Sinh bằng scripts/nhap/lo40_loi_nghe.mjs, đừng sửa tay. Lời nghe lấy nguyên văn từ script đã tạo audio;
-- phân tích (loại tài liệu, chủ đề, ý chính) ở lo40_loi_nghe_phan_tich.mjs. Chỉ VIP xem qua rpc xem_loi_nghe (194).



do $$
declare n int;
begin
  select count(*) into n from public.loi_nghe where phan_tich is not null;
  if n < 74 then raise exception 'lô 40: chỉ % bài có lời nghe và phân tích (cần 74)', n; end if;
end $$;
